def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        cache_for_typed = {}
        hits, misses = 0, 0

        def plain_wrapper(*args):
            nonlocal cache, hits
            if typed and args in cache_for_typed:
                hits += 1
                return cache_for_typed[args]
            elif args in cache:
                hits += 1
                return cache[args]
            else:
                misses += 1
                result = func(*args)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                if typed:
                    cache_for_typed[args] = result
                else:
                    cache[args] = result
                return result

        def typed_wrapper(*args, **kwargs):
            nonlocal cache_for_typed, hits
            args = (args, tuple(kwargs.items()))
            if args in cache_for_typed:
                hits += 1
                return cache_for_typed[args]
            else:
                misses += 1
                result = func(*args, **kwargs)
                if len(cache_for_typed) > maxsize:
                    cache_for_typed.popitem(last=False)
                cache_for_typed[args] = result
                return result

        return plain_wrapper if not typed else typed_wrapper
    return decorator

