    for arg in args:
        option = options_spec[arg]
        if option.get("required_when"):
            required_when_conditions = option.get("required_when")
            for required_when_condition in required_when_conditions:
                if required_when_condition["command"] == command_name:
                    if required_when_condition["value"] in args:
                        result.append(arg)
    return result
