def validate_min_max_args(self, args):
    if len(args) < self.min_args:
        raise ValueError("Insufficient arguments. Minimum number of arguments is " + str(self.min_args) + ".")
    if len(args) > self.max_args:
        raise ValueError("Too many arguments. Maximum number of arguments is " + str(self.max_args) + ".")
