def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith("-"):
            control_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args
```

This function takes in a list of arguments as input, and splits them into two dictionaries: `control_args` and `nested_args`.

Control args are arguments that start with a `-` and are used to control the behavior of the command. These arguments are not stored in the spec yml file.

Nested args are arguments that are not control args and are used by the Ansible playbooks and are stored in the spec yml file.

Custom args are custom ansible variables that can be used instead of the normal nested usage.

The function returns a tuple containing both dictionaries.

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    for key, value in values_dict.items():
        if key in self.COMMAND_ARGS[parser_name]:
            if self.COMMAND_ARGS[parser_name][key] == str:
                values_dict[key] = str(value)
            elif self.COMMAND_ARGS[parser_name][key] == int:
                values_dict[key] = int(value)
            elif self.COMMAND_ARGS[parser_name][key] == bool:
                values_dict[key] = bool(value)
            elif self.COMMAND_ARGS[parser_name][key] == float:
                values_dict[key] = float(value)
            elif self.COMMAND_ARGS[parser_name][key] == list:
                values_dict[key] = list(map(str, value))
            elif self.COMMAND_ARGS[parser_name][key] == dict:
                values_dict[key] = dict(value)
            else:
                raise ValueError(f"Unsupported type '{self.COMMAND_ARGS[parser_name][key]}' for argument '{key}'")

    return values_dict

def strip_root(path, root):
            """Remove root from path, throw exception on failure."""
            if not path.startswith(root):
                raise ValueError("Path " + path + " does not start with root " + root)
            return path[len(root):]
